import { Component, Element, Host, Prop, State, Watch, h } from "@stencil/core";
import { hasSlot } from "../../utils/slot";

/**
 * @since 2.0.1
 * @status stable
 *
 * @slot prefix - The list item's prefix content.
 * @slot - The list item's label.
 * @slot suffix - The list item's suffix content.
 *
 * @part base - The component's base wrapper.
 */

@Component({
	tag: "hbr-list-item",
	styleUrl: "list-item.scss",
	shadow: true,
})
export class HbrListItem {
	@Element() host: HTMLHbrListItemElement;

	/** The list item's variant styles such as anchor link menu(anchor). */
	@Prop({ reflect: true }) variant: string;

	/** Disables the list item. */
	@Prop({ reflect: true }) disabled: boolean;

	/** Indicates whether the list item is nested inside another list item. */
	// @Prop({ reflect: true }) nested: boolean;

	/** Indicates whether the list item is active. */
	@Prop({ reflect: true, mutable: true }) active: boolean;

	@State() hasPrefix = false;
	@State() hasSuffix = false;
	@State() hasChildren = false;

	@Watch("disabled")
	handleDisabledChange() {
		this.host.setAttribute("aria-disabled", this.disabled ? "true" : "false");
	}

	handleSlotChange() {
		this.hasPrefix = hasSlot(this.host, "prefix");
		this.hasSuffix = hasSlot(this.host, "suffix");
	}

	handleChildrenSlotChange() {
		this.hasChildren = hasSlot(this.host, "children");
	}

	componentWillLoad() {
		this.handleChildrenSlotChange();
	}

	render() {
		let parts = "item";
		if (this.disabled) {
			parts += " item--disabled";
		}
		if (this.active) {
			parts += " item--active";
		}

		return (
			// due to the wrapper blocking for SR to read <li> be child of <ul>, we need to add the role to the host
			<Host role="listitem">
				<li
					part="base"
					role="presentation"
					class={{
						"list-item": true,
						"list-item--active": this.active,
						"list-item--disabled": this.disabled,
						"list-item--has-prefix": this.hasPrefix,
						"list-item--has-suffix": this.hasSuffix,
						"list-item--has-children": this.hasChildren,
					}}
				>
					<div class="list-item__item" part={parts}>
						<div class="list-item__line" part="line" />
						<div class="list-item__indentation" part="indentation" />
						<span part="prefix" class={{ "list-item__prefix": this.hasPrefix }}>
							<slot
								onSlotchange={this.handleSlotChange.bind(this)}
								name="prefix"
							/>
						</span>
						<slot />
						<span part="suffix" class={{ "list-item__suffix": this.hasSuffix }}>
							<slot
								onSlotchange={this.handleSlotChange.bind(this)}
								name="suffix"
							/>
						</span>
					</div>
					{this.hasChildren && (
						<div class="list-item__children" part="children" role="list">
							<slot
								onSlotchange={this.handleChildrenSlotChange.bind(this)}
								name="children"
							/>
						</div>
					)}
				</li>
			</Host>
		);
	}
}
